def gen(rng):

    def build(n, rng, mode, cap=2400):
        # returns parent list (index 0 is the root), depth <= cap
        par = [-1] * n
        dep = [0] * n
        for i in range(1, n):
            if mode == "path" and i <= cap:
                p = i - 1
            elif mode == "star":
                p = 0
            elif mode == "binary":
                p = (i - 1) // 2
            elif mode == "cater":
                p = i - 1 if i <= 1000 else rng.randrange(1000)
            else:
                p = rng.randrange(i)
                while dep[p] >= cap:
                    p = rng.randrange(i)
            par[i] = p
            dep[i] = dep[p] + 1
        return par

    def edges_of(par, rng, shuffle=True):
        n = len(par)
        lab = list(range(1, n + 1))
        if shuffle:
            rng.shuffle(lab)
        e = [(lab[i], lab[par[i]]) if rng.random() < 0.5 else (lab[par[i]], lab[i]) for i in range(1, n)]
        rng.shuffle(e)
        return e

    def fmt(a, e):
        return str(len(a)) + "\n" + " ".join(map(str, a)) + ("\n" + "\n".join(f"{u} {v}" for u, v in e) if e else "")

    def values(n, hi, mode):
        if mode == "plain":
            return [rng.randint(1, hi) for _ in range(n)]
        if mode == "grouped":
            bases = [rng.randint(1, max(1, hi // 50)) for _ in range(max(1, n // 8 + 1))]
            return [min(hi, rng.choice(bases) * rng.randint(1, 40)) for _ in range(n)]
        return [rng.choice([6, 12, 18, 24, 30, 36, 42, 60]) * (10 ** (hi // 10**5 > 0) if False else 1) for _ in range(n)]

    tests = [
        "1\n7", "1\n1000000000", "2\n4 6\n1 2", "2\n4 6\n2 1", "3\n5 5 5\n1 2\n1 3", "3\n6 4 9\n2 1\n2 3",
        "5\n12 8 18 6 9\n1 2\n1 3\n3 4\n3 5", "4\n10 4 6 9\n1 2\n1 3\n1 4",
        "4\n12 18 6 9\n1 2\n2 3\n3 4",
    ]
    for _ in range(26):
        n = rng.randint(2, 14)
        mode = rng.choice(["random", "path", "star", "binary", "cater"])
        par = build(n, rng, mode)
        vm = rng.choice(["plain", "grouped", "small"])
        tests.append(fmt(values(n, rng.choice([10, 60, 1000, 10**9]), vm), edges_of(par, rng, shuffle=rng.random() < 0.8)))
    N = 100000
    for mode, vm, hi in (("random", "grouped", 10**9), ("path", "grouped", 10**6), ("cater", "small", 10**6),
                         ("binary", "grouped", 10**6), ("star", "plain", 10**6)):
        par = build(N, rng, mode)
        a = values(N, hi, vm)
        if hi == 10**9:
            a[rng.randrange(N)] = 10**9
        tests.append(fmt(a, edges_of(par, rng)))
    par = build(N, rng, "random")
    tests.append(fmt([720720] * N, edges_of(par, rng)))
    return tests
